    if best then M.go(best) S.task = __T["Ran from "] .. who end
end
function F.escape(who)
    S.hiding = true
    S.pauseUntil = os.clock() + val("sf_wait", 8) + 1
    local ok = pcall(function()
        local h = M.hum()
        local hp0 = h and h.Health or 0
        local far = val("sf_method", "Underground") ~= "Underground"
        if not far then
            local r = M.root()
            M.refreshFilter()
            local g = r and M.ground(r.Position, 20)
            if not g then far = true else
                M.hold(CFrame.new(g - Vector3.new(0, 14, 0)))
                S.task = __T["Hiding from "] .. who
                local t = os.clock()
                while RUNNING and M.alive() do
                    task.wait(0.2)
                    local hh = M.hum()
                    if hh and hh.Health < hp0 - hh.MaxHealth * 0.1 then far = true break end
                    local healed = not hh or hh.Health / math.max(1, hh.MaxHealth) >= math.min(0.95, val("sf_hp", 40) / 100 + 0.15)
                    if os.clock() - t >= val("sf_wait", 6) and (healed or os.clock() - t > 45) then break end
                    if hh and not healed then S.task = __T["Healing underground"] end
                end
            end
        end
        if far then F.flee(who) task.wait(val("sf_wait", 8) * 0.5) end
    end)
    S.hiding = false
    M.release(true)
    S.task = __T["Safe"]
    if not ok then LOG("escape err") end
end
F.hpLog = {}
task.spawn(function()
    local lastEsc = 0
    while RUNNING do
        local h = M.hum()
        if on("sf_escape") and M.alive() and h and not S.hiding then
            local t = os.clock()
            local frac = h.Health / math.max(1, h.MaxHealth)
            F.hpLog[#F.hpLog + 1] = { t, frac }
            while F.hpLog[1] and t - F.hpLog[1][1] > 1.5 do table.remove(F.hpLog, 1) end
            local drop = F.hpLog[1] and (F.hpLog[1][2] - frac) or 0
            local r = M.root()
            local near = r and T.nearThreat(r.Position, nil, 40)
            local hunted = t - S.huntedAt < 2
            local hurt = drop > 0.12 and (near or not S.fightAbove)
            if t - lastEsc > 2 and (hunted or hurt or frac < val("sf_hp", 40) / 100) then
                lastEsc = t
                local who = near and near.p.Name or (hunted and S.hunter) or "danger"
                S.huntedAt = 0
                S.escapes += 1
                F.hpLog = {}
                say(__T["Escaped "] .. who)
                task.spawn(F.escape, who)
            end
        else F.hpLog = {} end
        task.wait(0.1)
    end
end)
