function E.pickTrait(list)
    if not on("tr_on") or type(list) ~= "table" then return end
    local order = {}
    for i, n in ipairs(E.traitOrder or {}) do order[n] = i end
    local best, bi
    for i, id in ipairs(list) do
        local score = order[id] or 99
        if not bi or score < bi then best, bi = i, score end
    end
    if best then task.delay(0.6, function() fireR("PickTrait", best) LOG("trait", list[best]) end) end
end
