function E.spiders()
    local o = {}
    for id, d in pairs(D.SpiderDefs or {}) do
        if type(d) == "table" and d.Id == id and d.Parent and (d.Cost or 0) > 0 and d.Tier and not d.Robux and not d.Special then o[#o + 1] = d end
    end
    table.sort(o, function(a, b) if a.Tier ~= b.Tier then return a.Tier < b.Tier end return a.Id < b.Id end)
    return o
end
function E.nextBug()
    local cur, lv, coins = lp:GetAttribute("SpiderId"), M.lvl(), lp:GetAttribute("Coins") or 0
    local un = S.profile and S.profile.Unlocked or {}
    local pref = val("ev_branch", "Any")
    local best, bs
    for _, d in ipairs(E.spiders()) do
        if d.Parent == cur then
            local owned = un[d.Id] == true
            local sc = (owned and 0 or d.Cost) + ((pref ~= "Any" and d.Family ~= pref) and 1e6 or 0)
            if not bs or sc < bs then best, bs = d, sc end
        end
    end
    return best, best and (un[best.Id] == true), coins, lv
end
function E.climb()
    local d, owned, coins, lv = E.nextBug()
    if not d then E.climbTxt = "Top of this branch" return end
    if lv < val("ev_climb_lv", 100) then E.climbTxt = string.format("Next: %s at Lv %d", tostring(d.Name or d.Id), val("ev_climb_lv", 100)) return end
    if not owned then
        if coins < (d.Cost or 0) then E.climbTxt = string.format("Next: %s · %d/%d coins", tostring(d.Name or d.Id), coins, d.Cost) return end
        local ok, msg = invokeR("TreeAction", "Unlock", d.Id)
        LOG("climb unlock", d.Id, ok, msg)
        if not ok and not tostring(msg):lower():find("already") then E.climbTxt = tostring(msg or "Can't unlock") return end
        task.wait(1)
    end
    local ok, msg
    for _ = 1, 4 do
        ok, msg = invokeR("TreeAction", "Play", d.Id)
        if ok or lp:GetAttribute("SpiderId") == d.Id then ok = true break end
        task.wait(2)
    end
    LOG("climb play", d.Id, ok, msg)
    if ok then say(__T["Now playing "] .. tostring(d.Name or d.Id)) E.climbTxt = __T["Now "] .. tostring(d.Name or d.Id) end
end
