end)
F.huntStep = function()
    local r = M.root()
    if not (r and M.alive()) then return false end
    local me, best, bd = M.lvl(), nil, nil
    local thr = T.threats()
    for _, p in ipairs(Players:GetPlayers()) do
        local c = p ~= lp and p.Character
        local pr = c and c:FindFirstChild("HumanoidRootPart")
        if pr and T.hp(c) > 0 and not c:GetAttribute("Shielded") and not c:GetAttribute("Protected") and (c:GetAttribute("Level") or 999) <= me - val("pv_gap", 3) then
            local inSafe = false
            for _, z in ipairs(D.Safe) do if (Vector2.new(pr.Position.X, pr.Position.Z) - z.Center).Magnitude <= z.Radius then inSafe = true end end
            if not inSafe and not T.nearThreat(pr.Position, thr) then
                local d = (pr.Position - r.Position).Magnitude
                if not bd or d < bd then best, bd = c, d end
            end
        end
    end
    if not best then return false end
    F.fight(best, __T["Hunting "] .. best.Name)
    return true
end
