    AD:AddToggle("ka_players", { Text = __T["Smaller Players"], Default = false })
    AD:SetupDependencies({ { Toggles.ka_on, true } })
    local P = Tab:AddRightGroupbox(__T["Hunt Players"], "target")
    P:AddToggle("pv_hunt", { Text = __T["Hunt Smaller Players"], Default = false, Tooltip = __T["Skips shielded players and nests"] })
    local PD = P:AddDependencyBox()
    PD:AddSlider("pv_gap", { Text = __T["At Least Smaller By"], Default = 3, Min = 1, Max = 50, Rounding = 0, Suffix = __T[" lv"] })
    PD:SetupDependencies({ { Toggles.pv_hunt, true } })
    track(RunService.Heartbeat:Connect(function()
        if not on("ka_on") or F.anyFarm() or os.clock() < F.nextBite then return end
        local r = M.root()
        if not (r and M.alive()) then return end
        local best, bd
        local reach = (lp:GetAttribute("Reach") or 6) + 3
        local function consider(m)
            local p = T.mpos(m)
            if p and T.hp(m) > 0 then
                local d = (p - r.Position).Magnitude - (m:GetAttribute("Radius") or 1)
                if d < reach and (not bd or d < bd) then best, bd = m, d end
            end
        end
        local bf, kf = Workspace:FindFirstChild("Bugs"), Workspace:FindFirstChild("Breakables")
        if on("ka_bugs") and bf then for _, m in ipairs(bf:GetChildren()) do consider(m) end end
        if on("ka_food") and kf then for _, m in ipairs(kf:GetChildren()) do consider(m) end end
        if on("ka_players") and not lp:GetAttribute("Shielded") then
            for _, p in ipairs(Players:GetPlayers()) do
                local c = p ~= lp and p.Character
                if c and not c:GetAttribute("Shielded") and not c:GetAttribute("Protected") and (c:GetAttribute("Level") or 999) < M.lvl() then consider(c) end
            end
        end
        if best then F.bite(best) F.ability(best) end
    end))
end)
