    local Tab = Window:AddTab(__T["Settings"], "settings")
    local Menu = Tab:AddLeftGroupbox(__T["Menu"], "menu")
    Menu:AddLabel(__T["Menu Key"]):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = __T["Menu Key"] })
    Library.ToggleKeybind = Opt.MenuKeybind
    Menu:AddDropdown("ui_scale", { Text = __T["UI Scale"], Values = { "60%", "75%", "90%", "100%", "110%", "125%" }, Default = Library.IsMobile and "75%" or "100%", Callback = function(v) pcall(function() Library:SetDPIScale(tonumber(tostring(v):match("%d+")) or 100) end) task.delay(0.2, function() if UI.center then UI.center() end end) end })
    if Library.IsMobile then pcall(function() Library:SetDPIScale(75) end) end
    Menu:AddButton({ Text = __T["Unload"], Func = function() pcall(_G.__CW_BUGEVO_CLEAN) end })
    local SV = Tab:AddLeftGroupbox(__T["Server"], "server")
    SV:AddButton({ Text = __T["Rejoin"], Func = function() pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) end) end })
    SV:AddButton({ Text = __T["Server Hop"], Func = function()
        task.spawn(function()
            local ok, body = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100") end)
            local data = ok and HttpService:JSONDecode(body)
            for _, s in ipairs(data and data.data or {}) do
                if s.id ~= game.JobId and (s.playing or 0) < (s.maxPlayers or 15) - 1 then pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, lp) end) return end
            end
            notify(__T["No other server found"])
        end)
    end })
    SaveManager:SetLibrary(Library)
    ThemeManager:SetLibrary(Library)
    SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg" })
    ThemeManager:SetFolder("COMBO_WICK_BUGEVO")
    SaveManager:SetFolder("COMBO_WICK_BUGEVO")
    ThemeManager:ApplyToTab(Tab)
    pcall(function()
        if not (isfile and isfile("COMBO_WICK_BUGEVO/themes/default.txt")) then ThemeManager:ApplyTheme("Tokyo Night") end
    end)
    SaveManager:BuildConfigSection(Tab)
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    if isfile and isfile("COMBO_WICK_BUGEVO/settings/auto.json") then SaveManager:Load("auto") else SaveManager:LoadAutoloadConfig() end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() SaveManager:Save("auto") end) end end)
    end
    local function skip(k) k = tostring(k); return k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
notify(__T["Loaded"])

end
